function demoTransform(part,idx){const k=modelKey(active),v=demoValue/100;const p=part.slice();let transform=null;
 if(k==='parking-barrier'&&idx>=1){const theta=v*Math.PI*.42;transform=([x,y,z])=>{const dx=x+1.7,dy=y-1.11;return [-1.7+dx*Math.cos(theta)-dy*Math.sin(theta),1.11+dx*Math.sin(theta)+dy*Math.cos(theta),z]}}
 if(k==='retractable-bollard'&&(idx===2)){p[4]=Math.max(.035,p[4]*(1-v));}
 if(k==='roller-shutter'&&idx>=3){p[1]+=2.3*v;if(p[1]>2.4)return null}
 if(k==='ptz-camera'&&idx>=1){const theta=(v-.5)*Math.PI;transform=([x,y,z])=>[x*Math.cos(theta)-z*Math.sin(theta),y,x*Math.sin(theta)+z*Math.cos(theta)]}
 if(k==='sliding-vehicle-gate'&&idx>=3)p[0]-=1.4*v;
 if(k==='security-lighting'&&idx===4)p[6]=v>.5?'#fff3b5':'#a2aaa7';
 if(k==='emergency-luminaire'&&(idx===6||idx===7))p[6]=v>.5?'#fff3bd':'#858b84';
 if(k==='emergency-luminaire'&&idx===8)p[6]=v>.5?'#89ba91':'#5a6b63';
 if(k==='visitor-badge-printer'&&(idx===4||idx===5)){if(v<.05)return null;p[2]-=.32*(1-v);}
 if(k==='equipment-status-display'&&idx>=5){if(v<.5&&idx>=6&&idx<20)return null;if(idx===5)p[6]=v>.5?'#456978':'#24343b';if(idx===20)p[6]=v>.5?'#79a38c':'#54645d';}

 return {part:p,transform}
}
