// Surface appearance keyed by visible assembly name; illustrative, not a product specification.
function appearanceForPart(name,color){
 const n=name.toLowerCase();
 if(/wall surface|column surfaces|top finish|illustrative wall/.test(n))return [.89,.0];
 if(/window frame/.test(n))return [.40,.40];
 if(/optical|glazing|glass|dome|window/.test(n))return [.14,.08];
 if(/luminous/.test(n))return [.22,.02];
 if(/screen|display area|display surface|touch interface|status indication|indicator/.test(n))return [.25,.02];
 if(/rails|posts|frame|bracket|mounting|upright|steel|wire|shaft|support/.test(n))return [.37,.48];
 if(/housing|enclosure|cabinet|chassis|faceplate|panel/.test(n))return [.53,.14];
 if(/marking|belt|keypad|button|card|planting/.test(n))return [.78,.02];
 return undefined;
}
