const groupCache=models.map((m,index)=>{const groups=componentGroups[index]||m.b.map((_,i)=>['示意构件 '+String(i+1).padStart(2,'0'),'Illustrative element '+String(i+1).padStart(2,'0'),[i]]);const lookup=[];groups.forEach((g,j)=>g[2].forEach(i=>lookup[i]=j));return {groups,lookup}});
function groupsForModel(){return groupCache[active].groups}
function groupOf(i){return groupCache[active].lookup[i]??-1}
function partName(i){const g=groupsForModel()[groupOf(i)];return g?g[z?0:1]:(z?'示意构件':'Illustrative element')}
function renderPartPreview(){
 const host=document.querySelector('#lab-part-preview');if(!host)return;
 host.replaceChildren();
 const make=(tag,txt)=>{const e=document.createElement(tag);if(txt)e.textContent=txt;return e};
 const title=make('h4',z?'构件近景':'Assembly detail');title.style.margin='10px 0 4px';host.append(title);
 const group=groupOf(picked),g=groupsForModel()[group];
 if(!g){host.append(make('p',z?'选择三维模型上的构件，或点击上方名称，查看独立近景。':'Select a model element or its name above for an independent detail view.'));return;}
 const head=make('strong',g[z?0:1]);host.append(head);
 const polygons=[];const all=[];
 const project=([x,y,z])=>[x*.82-z*.57,-y*.85+(x*.57+z*.82)*.37,(x*.57+z*.82)*.85+y*.37];
 for(const i of g[2]){const part=models[active].b[i];if(!part)continue;const m=mesh(part),v=m.vertices.map(project);all.push(...v);for(const f of m.polys){const points=f.map(j=>v[j]);polygons.push({points,color:m.color,depth:points.reduce((a,p)=>a+p[2],0)/points.length});}}
 if(!all.length)return;
 const minX=Math.min(...all.map(p=>p[0])),maxX=Math.max(...all.map(p=>p[0])),minY=Math.min(...all.map(p=>p[1])),maxY=Math.max(...all.map(p=>p[1]));
 const scale=Math.min(280/Math.max(.03,maxX-minX),150/Math.max(.03,maxY-minY)),ox=160-(minX+maxX)*scale/2,oy=90-(minY+maxY)*scale/2;
 const ns='http://www.w3.org/2000/svg',svg=document.createElementNS(ns,'svg');svg.setAttribute('viewBox','0 0 320 180');svg.setAttribute('role','img');svg.setAttribute('aria-label',g[z?0:1]);svg.style.cssText='display:block;width:100%;max-height:210px;background:#19262c;border:1px solid #43545b;border-radius:6px;margin:8px 0';
 polygons.sort((a,b)=>a.depth-b.depth);for(const p of polygons){const el=document.createElementNS(ns,'polygon');el.setAttribute('points',p.points.map(v=>(ox+v[0]*scale).toFixed(2)+','+(oy+v[1]*scale).toFixed(2)).join(' '));el.setAttribute('fill',p.color);el.setAttribute('stroke','#283a42');el.setAttribute('stroke-width','.5');svg.append(el);}
 host.append(svg,make('p',z?'独立近景用于识别模型中的构件形态；主模型保留完整装配关系。':'The detail view identifies the illustrated assembly; the main model retains the complete context.'));
 const back=make('button',z?'返回完整装配':'Return to full assembly');back.type='button';back.onclick=()=>setPicked(picked);host.append(back);
}
function setPicked(i){const group=groupOf(i),current=groupOf(picked);if(productView&&(productStands[active]||[]).includes(i)){productView=false;document.querySelector('[data-act=product]').setAttribute('aria-pressed','false');zoom=1}picked=group<0||group===current?-1:groupsForModel()[group][2][0];document.querySelector('#lab-status').textContent=picked<0?(z?'已清除选择':'Selection cleared'):(z?'已选构件组：':'Selected assembly group: ')+partName(picked);document.querySelectorAll('#lab-parts button').forEach(b=>b.setAttribute('aria-pressed',String(Number(b.dataset.part)===picked)));renderPartPreview();render()}
function updateParts(){const el=document.querySelector('#lab-parts');if(!el)return;el.replaceChildren();for(const g of groupsForModel()){const b=document.createElement('button'),i=g[2][0];b.textContent=g[z?0:1];b.dataset.part=i;b.setAttribute('aria-pressed','false');b.onclick=()=>setPicked(i);el.append(b)}document.querySelector('#lab-status').textContent=z?'点击模型或构件名称高亮同类构件':'Select the model or an assembly name to highlight the group'}
