 // Hotspots associate components with ordinary architectural contexts; they are not engineering installation coordinates.
 function contextPoint(k,j){
  const type=contextByKey(k)[1];
  if(zone===0){
   if(type==='Boundary and spatial separation')return [-3.9,.25,2.35];
   if(type==='Routine circulation and service')return [2.9,.20,1.65];
   if(type==='Information and operations')return [4.25,1.2,-.95];
   if(type==='Public space and welfare')return [1.4,.5,1.4];
   return [scene===2?4.35:scene===0?4.65:scene===1?4.25:-1.8,1.2,-.95];
  }
  if(zone===1){
   if(type==='Routine circulation and service')return [j%2?-3.6:3.65,.95,-.3];
   if(type==='Information and operations')return [-3.6,1.25,-1.45];
   if(type==='Public space and welfare')return [2.55,.55,.75];
   if(type==='Boundary and spatial separation')return [-3.6,.3,.8];
   return [3.65,1.1,-1.45];
  }
  if(type==='Public space and welfare')return [j%2?-1.05:1.05,.65,1.5];
  if(type==='Routine circulation and service')return [-3.8,.9,-.85];
  if(type==='Information and operations')return [0,1.3,-1.8];
  if(type==='Boundary and spatial separation')return [0,.15,2.15];
  return [j%2?3.8:-3.8,1.1,j%2?-1.8:1.55];
 }
 let lastSceneGeometry=[],cachedScene=null,cachedFallback=null;
 const keyListBoundaryIndex=()=>keys(zone).indexOf('fence');
 function renderHotspots(project,w,h){
  const host=$('#studio-hotspots');if(!host)return;host.replaceChildren();
  if(!showDevices||!showFurniture)return;
  const markers=[],occupied=[],clamp=(v,l,r)=>Math.max(l,Math.min(r,v));
  keys(zone).forEach((k,j)=>{const i=find(k);if(i<0)return;const group=lastSceneGeometry.filter(o=>o.device===j&&o.g===zone);if(!group.length)return;
   const anchor=[group[0].p[0],group[0].p[1]+group[0].p[4],group[0].p[2]],p=project(anchor);markers.push({k,j,i,p});
  });
  markers.sort((a,b)=>Number(b.j===selected)-Number(a.j===selected)||a.j-b.j);
  for(const {k,j,i,p} of markers){
   const radius=j===selected?18:15,ox=clamp(p[0],radius+3,w-radius-3),oy=clamp(p[1]-12,42,h-radius-25);
   let best=[ox,oy],score=Infinity;
   for(let ring=0;ring<9;ring++){const n=ring===0?1:ring*8;
    for(let v=0;v<n;v++){const ang=v*2*Math.PI/n,xx=clamp(ox+Math.cos(ang)*ring*18,radius+3,w-radius-3),yy=clamp(oy+Math.sin(ang)*ring*18,42,h-radius-25);
     const conflict=occupied.reduce((sum,q)=>sum+Math.max(0,radius+q[2]+4-Math.hypot(xx-q[0],yy-q[1]))**2,0),cost=conflict*2000+Math.hypot(xx-ox,yy-oy);
     if(cost<score){score=cost;best=[xx,yy]}
    }if(score<ring*18+1)break;
   }
   const [x,y]=best;occupied.push([x,y,radius]);
   if(Math.hypot(x-p[0],y-p[1])>18){ctx.beginPath();ctx.moveTo(p[0],p[1]);ctx.lineTo(x,y);ctx.strokeStyle=j===selected?'#f1cb91':'#adbec0';ctx.lineWidth=1;ctx.stroke()}
   const button=btn(host,String(j+1),()=>{selected=j;renderControls();draw()},selected===j);button.style.left=x+'px';button.style.top=y+'px';button.title=t(library.models[i].n)+' · '+t(contextByKey(k));button.setAttribute('aria-label',button.title);
  }
 }

